
window.OVI=[['Luar rumah','data:image/jpeg;base64,'],['Bukit tepi danau','data:image/jpeg;base64,'],['Dalam rumah','data:image/jpeg;base64,'],['Kedai Lentera','data:image/jpeg;base64,']];
window.ovHTML=()=>'<hr><b>Tampilan game</b> <small>ketuk gambar untuk memperbesar</small><div class=ovg>'+OVI.map((a,i)=>'<button class=ovc onclick="ovOpen('+i+')" aria-label="'+a[0]+'"><img src="'+a[1]+'" alt="'+a[0]+'" draggable=false><span>'+a[0]+'</span></button>').join('')+'</div>';
window.ovOpen=i=>{let o=document.getElementById('ovl');if(!o){o=document.createElement('div');o.id='ovl';o.innerHTML='<img alt=""><div></div>';o.onclick=()=>o.classList.remove('on');(document.getElementById('w')||document.body).appendChild(o)}o.firstChild.src=OVI[i][1];o.lastChild.textContent=OVI[i][0]+' · ketuk untuk menutup';o.classList.add('on')};
